SELECT TOP 1 @ID_ae7c80fb5431 = [ID] FROM [${mjSchema}].[RemoteOperation] WHERE [OperationKey] = N'Orders.SpawnRenewals' ORDER BY CASE WHEN [ID] = @ID_ae7c80fb5431 THEN 0 ELSE 1 END
SELECT TOP 1 @CategoryID_ae7c80fb5431 = [ID] FROM [${mjSchema}].[RemoteOperationCategory] WHERE [Name] = N'Subscriptions' ORDER BY CASE WHEN [ID] = @CategoryID_ae7c80fb5431 THEN 0 ELSE 1 END
EXEC [${mjSchema}].spUpdateRemoteOperation @Name = @Name_ae7c80fb5431,
