-- Save MJ: Authorization Roles (core SP call only)
DECLARE @ID_86b3803ea243 UNIQUEIDENTIFIER,
@AuthorizationID_86b3803ea243 UNIQUEIDENTIFIER,
@RoleID_86b3803ea243 UNIQUEIDENTIFIER,
@Type_86b3803ea243 NCHAR(10)
SET
  @ID_86b3803ea243 = '95C1EB47-69B0-49AB-A007-FC035EB5CB86'
SET
  @AuthorizationID_86b3803ea243 = '78CAE9AB-DD73-4128-AC23-6A58BE45302A'
SET
  @RoleID_86b3803ea243 = '1318256E-6FE4-4349-82D6-FED8724E7103'
SET
  @Type_86b3803ea243 = N'Allow'
SELECT TOP 1 @AuthorizationID_86b3803ea243 = [ID] FROM [${mjSchema}].[Authorization] WHERE [Name] = N'MJ.BizApps.Orders.Coverage.RunAlongside' ORDER BY CASE WHEN [ID] = @AuthorizationID_86b3803ea243 THEN 0 ELSE 1 END
SELECT TOP 1 @RoleID_86b3803ea243 = [ID] FROM [${mjSchema}].[Role] WHERE [Name] = N'Account Director' ORDER BY CASE WHEN [ID] = @RoleID_86b3803ea243 THEN 0 ELSE 1 END
IF @AuthorizationID_86b3803ea243 IS NOT NULL AND @RoleID_86b3803ea243 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM [${mjSchema}].[AuthorizationRole]
               WHERE [ID] = @ID_86b3803ea243
                  OR ([AuthorizationID] = @AuthorizationID_86b3803ea243 AND [RoleID] = @RoleID_86b3803ea243))
EXEC [${mjSchema}].spCreateAuthorizationRole @ID = @ID_86b3803ea243,
  @AuthorizationID = @AuthorizationID_86b3803ea243,
  @RoleID = @RoleID_86b3803ea243,
  @Type = @Type_86b3803ea243;

GO

